3-4 按键控制LED&amp;光敏传感器控制LED使用模块化编程，当遇到多外设时，将每个设备的代码分成.c和.h分开来写，有利于使代码结构清晰，也便于移植。
mian.c
#include &quot;stm32f10x.h&quot;                  // Device header#include &quot;Delay.h&quot;#include &quot;LED.h&quot;#include &quot;Key.h&quot;// 定义全局变量KeyNum// 用于接收按键数据的载体uint8_t KeyNum;int main(void)&#123;	LED_Init();	Key_Init();		while(1)	&#123;		KeyNum = Key_GetNum();		if (KeyNum == 1)		&#123;			LED_1_Turn();		&#125;		else if(KeyNum == 2)		&#123;			LED_3_Turn();		&#125;	&#125;&#125;

 KEY.c
#include &quot;stm32f10x.h&quot;#include &quot;Delay.h&quot;// 初始化void Key_Init(void)&#123;	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);	GPIO_InitTypeDef GPIO_Structure;	GPIO_Structure.GPIO_Mode = GPIO_Mode_IPU;	GPIO_Structure.GPIO_Pin = GPIO_Pin_1 | GPIO_Pin_11;	GPIO_Structure.GPIO_Speed = GPIO_Speed_50MHz; // 输入时速度可不写	GPIO_Init(GPIOB, &amp;GPIO_Structure);&#125;// 按键的数据uint8_t Key_GetNum(void)&#123;	// 初始数据为 0	uint8_t KeyNum = 0;	// 原理：当读取到(GPIOB, GPIO_Pin_1)端口低电平时，将KeyNum设置为 1	// GPIO_ReadInputDataBit--&gt;**读取指定端口管脚的输入**	if (GPIO_ReadInputDataBit(GPIOB, GPIO_Pin_1) == 0)	&#123;		Delay_ms(20);// 消除抖动		while(GPIO_ReadInputDataBit(GPIOB, GPIO_Pin_1) == 0);		Delay_ms(20);		KeyNum = 1;	&#125;	// 同上，将KeyNum设置为 2	if (GPIO_ReadInputDataBit(GPIOB, GPIO_Pin_11) == 0)	&#123;		Delay_ms(20);		while(GPIO_ReadInputDataBit(GPIOB, GPIO_Pin_11) == 0);		Delay_ms(20);		KeyNum = 2;	&#125;			return KeyNum;&#125;

KEY.h
#ifndef __Key_H#define __Key_Hvoid Key_Init(void);uint8_t Key_GetNum(void);#endif

Delay.c
#include &quot;stm32f10x.h&quot;/**  * @brief  微秒级延时  * @param  xus 延时时长，范围：0~233015  * @retval 无  */void Delay_us(uint32_t xus)&#123;	SysTick-&gt;LOAD = 72 * xus;				//设置定时器重装值	SysTick-&gt;VAL = 0x00;					//清空当前计数值	SysTick-&gt;CTRL = 0x00000005;				//设置时钟源为HCLK，启动定时器	while(!(SysTick-&gt;CTRL &amp; 0x00010000));	//等待计数到0	SysTick-&gt;CTRL = 0x00000004;				//关闭定时器&#125;/**  * @brief  毫秒级延时  * @param  xms 延时时长，范围：0~4294967295  * @retval 无  */void Delay_ms(uint32_t xms)&#123;	while(xms--)	&#123;		Delay_us(1000);	&#125;&#125; /**  * @brief  秒级延时  * @param  xs 延时时长，范围：0~4294967295  * @retval 无  */void Delay_s(uint32_t xs)&#123;	while(xs--)	&#123;		Delay_ms(1000);	&#125;&#125; 

Delay.h
#ifndef __DELAY_H#define __DELAY_Hvoid Delay_us(uint32_t us);void Delay_ms(uint32_t ms);void Delay_s(uint32_t s);#endif

 LED.c
#ifndef __DELAY_H#define __DELAY_Hvoid Delay_us(uint32_t us);void Delay_ms(uint32_t ms);void Delay_s(uint32_t s);#endif

LED.h
// LED.c 用于存放驱动程序的主体代码#include &quot;stm32f10x.h&quot;void LED_Init(void)&#123;	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);		GPIO_InitTypeDef GPIO_InitStructure;	GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;	GPIO_InitStructure.GPIO_Pin = GPIO_Pin_1 | GPIO_Pin_3;	GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;	GPIO_Init(GPIOA, &amp;GPIO_InitStructure);		GPIO_SetBits(GPIOA, GPIO_Pin_1 | GPIO_Pin_3);&#125;// LED_1 开启void LED_1_ON(void)&#123;	GPIO_ResetBits(GPIOA, GPIO_Pin_1);&#125;// LED_3 开启void LED_3_ON(void)&#123;	GPIO_ResetBits(GPIOA, GPIO_Pin_3);&#125;// LED_1 关闭void LED_1_OFF(void)&#123;	GPIO_SetBits(GPIOA, GPIO_Pin_1);&#125;// LED_3 关闭void LED_3_OFF(void)&#123;	GPIO_SetBits(GPIOA, GPIO_Pin_3);&#125;// 反转LED_1void LED_1_Turn(void)&#123;	// 原理：读取端口为 0，则置 1，读取端口为 1，则重置	// **读取指定端口管脚的输出**	if(GPIO_ReadOutputDataBit(GPIOA, GPIO_Pin_1) == 0)	&#123;		GPIO_SetBits(GPIOA, GPIO_Pin_1);	&#125;	else	&#123;		GPIO_ResetBits(GPIOA, GPIO_Pin_1);	&#125;&#125;// 同上void LED_3_Turn(void)&#123;	if(GPIO_ReadOutputDataBit(GPIOA, GPIO_Pin_3) == 0)	&#123;		GPIO_SetBits(GPIOA, GPIO_Pin_3);	&#125;	else	&#123;		GPIO_ResetBits(GPIOA, GPIO_Pin_3);	&#125;&#125;

 LED.c	(光敏)
// LED.c 用于存放驱动程序的主体代码#include &quot;stm32f10x.h&quot;void LED_Init(void)&#123;	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);		GPIO_InitTypeDef GPIO_InitStructure;	GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;	GPIO_InitStructure.GPIO_Pin = GPIO_Pin_1 | GPIO_Pin_3;	GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;	GPIO_Init(GPIOA, &amp;GPIO_InitStructure);		GPIO_SetBits(GPIOA, GPIO_Pin_1 | GPIO_Pin_3);&#125;// LED_1 开启void LED_1_ON(void)&#123;	GPIO_ResetBits(GPIOA, GPIO_Pin_1);&#125;// LED_3 开启void LED_3_ON(void)&#123;	GPIO_ResetBits(GPIOA, GPIO_Pin_3);&#125;// LED_1 关闭void LED_1_OFF(void)&#123;	GPIO_SetBits(GPIOA, GPIO_Pin_1);&#125;// LED_3 关闭void LED_3_OFF(void)&#123;	GPIO_SetBits(GPIOA, GPIO_Pin_3);&#125;// 反转LED_1void LED_1_Turn(void)&#123;	// 原理：读取端口为 0，则置 1，读取端口为 1，则重置	// **读取指定端口管脚的输出**	if(GPIO_ReadOutputDataBit(GPIOA, GPIO_Pin_1) == 0)	&#123;		GPIO_SetBits(GPIOA, GPIO_Pin_1);	&#125;	else	&#123;		GPIO_ResetBits(GPIOA, GPIO_Pin_1);	&#125;&#125;// 同上void LED_3_Turn(void)&#123;	if(GPIO_ReadOutputDataBit(GPIOA, GPIO_Pin_3) == 0)	&#123;		GPIO_SetBits(GPIOA, GPIO_Pin_3);	&#125;	else	&#123;		GPIO_ResetBits(GPIOA, GPIO_Pin_3);	&#125;&#125;

