#include &quot;Device/Include/stm32f10x.h&quot;   // Device header#include &quot;conter_sensor.h&quot; int16_t num = 0; //初始化红外对射式计数器//中断信号： GPIO-&gt;AFIO-&gt;EXTI-&gt;NVIC-&gt;CPUvoid ConterSensor_Init()&#123;	//开启GPIOB的时钟	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB,ENABLE);		//开启AFIO的时钟	RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO,ENABLE);		//配置GPIO  B14	GPIO_InitTypeDef My_GPIO_Initstruct;	My_GPIO_Initstruct.GPIO_Pin = GPIO_Pin_14;	My_GPIO_Initstruct.GPIO_Mode = GPIO_Mode_IPU;	My_GPIO_Initstruct.GPIO_Speed = GPIO_Speed_50MHz;	GPIO_Init(GPIOB,&amp;My_GPIO_Initstruct);		//配置AFIO数据选择器	GPIO_EXTILineConfig(GPIO_PortSourceGPIOB,GPIO_PinSource14);		//配置EXTI外部中断	EXTI_InitTypeDef My_EXTI_InitStructure;	My_EXTI_InitStructure.EXTI_Line = EXTI_Line14;//指定要配置的中断线	My_EXTI_InitStructure.EXTI_LineCmd = ENABLE;//指定中断是否使能	My_EXTI_InitStructure.EXTI_Mode = EXTI_Mode_Interrupt;//配置中断模式，是中断模式还是事件模式	My_EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Rising_Falling;//指定触发方式，是上升沿触发还是下降沿触发还是上下均触发，rising上升触发，falling下降沿触发	EXTI_Init(&amp;My_EXTI_InitStructure);		//配置NVIC中断管理器，配置中断优先级	NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);		//初始化NVIC,每个中断通道对应一个中断函数，在触发中断时系统会自动调用	NVIC_InitTypeDef My_NVIC_Initstructure;	My_NVIC_Initstructure.NVIC_IRQChannel = EXTI15_10_IRQn;//选中要配置的中断通道	My_NVIC_Initstructure.NVIC_IRQChannelCmd = ENABLE;//指定通道使能还是失能	My_NVIC_Initstructure.NVIC_IRQChannelPreemptionPriority = 1;//配置抢占优先级	My_NVIC_Initstructure.NVIC_IRQChannelSubPriority = 1;//配置响应优先级	NVIC_Init(&amp;My_NVIC_Initstructure);&#125; int16_t Get_ConterNum()&#123;	return num;&#125; //中断函数在启动文件里面查找void EXTI15_10_IRQHandler(void)&#123;	if(EXTI_GetITStatus(EXTI_Line14) == SET)	&#123;		num++;		EXTI_ClearITPendingBit(EXTI_Line14);	&#125;&#125;

