earITPendingBit(EXTI_Line0);//清除标志位	&#125;&#125; void EXTI1_IRQHandler(void)&#123;	if(EXTI_GetFlagStatus(EXTI_Line1) == SET)	&#123;		if(GPIO_ReadInputDataBit(GPIOB,GPIO_Pin_0) == 0)		&#123;			encoder_num++;		&#125;				EXTI_ClearITPendingBit(EXTI_Line1);	&#125;&#125;

