lter); //选择ETR通过外部时钟模式1输入的时钟void TIM_ETRClockMode1Config(TIM_TypeDef* TIMx, uint16_t TIM_ExtTRGPrescaler, uint16_t TIM_ExtTRGPolarity,                             uint16_t ExtTRGFilter); //选择ETR通过外部时钟模式2输入的时钟void TIM_ETRClockMode2Config(TIM_TypeDef* TIMx, uint16_t TIM_ExtTRGPrescaler,                              uint16_t TIM_ExtTRGPolarity, uint16_t ExtTRGFilter); //单独用来配置ETR引脚的预分频器、极性、滤波器这些参数void TIM_ETRConfig(TIM_TypeDef* TIMx, uint16_t TIM_ExtTRGPrescaler, uint16_t TIM_ExtTRGPolarity,                   uint16_t ExtTRGFilter); //直接单独配置预分配值PSC，参数2是写入模式，可选择是听从安排，在更新事件生效；或者是在写入后手动//产生一个更新事件，让这个值立刻生效void TIM_PrescalerConfig(TIM_TypeDef* TIMx, uint16_t Prescaler, uint16_t TIM_PSCReloadMode); //改变计数器的计数模式void TIM_CounterModeConfig(TIM_TypeDef* TIMx, uint16_t TIM_CounterMode);  void TIM_SelectInputTrigger(TIM_TypeDef* TIMx, uint16_t TIM_InputTriggerSource);  void TIM_EncoderInterfaceConfig(TIM_TypeDef* TIMx, uint16_t TIM_EncoderMode,                                uint16_t TIM_IC1Polarity, uint16_t TIM_IC2Polarity); //配置强制输出模式，运行中想要强制改变输出的波形，直接输出高或低电平就用这个//不过其效果和改变PWM占空比100%或0%的效果是一样的void TIM_ForcedOC1Config(TIM_TypeDef* TIMx, uint16_t TIM_ForcedAction);void TIM_ForcedOC2Config(TIM_TypeDef* TIMx, uint16_t TIM_ForcedAction);void TIM_ForcedOC3Config(TIM_TypeDef* TIMx, uint16_t TIM_ForcedAction);void TIM_ForcedOC4Config(TIM_TypeDef* TIMx, uint16_t TIM_ForcedAction); //自动重装器预装功能配置void TIM_ARRPreloadConfig(TIM_TypeDef* TIMx, FunctionalState NewState);  void TIM_SelectCOM(TIM_TypeDef* TIMx, FunctionalState NewState);  void TIM_SelectCCDMA(TIM_TypeDef* TIMx, FunctionalState NewState);  void TIM_CCPreloadControl(TIM_TypeDef* TIMx, FunctionalState NewState); //配置CCR寄存器的预装功能，也就是影子寄存器（写入的值不会立即生效，而是在事件更新后才生效）void TIM_OC1PreloadConfig(TIM_TypeDef* TIMx, uint16_t TIM_OCPreload);void TIM_OC2PreloadConfig(TIM_TypeDef* TIMx, uint16_t TIM_OCPreload);void TIM_OC3PreloadConfig(TIM_TypeDef* TIMx, uint16_t TIM_OCPreload);void TIM_OC4PreloadConfig(TIM_TypeDef* TIMx, uint16_t TIM_OCPreload); /