d); //单独用来更改CCR寄存器值的，PWM输出更改占空比就用这个函数void TIM_SetCompare1(TIM_TypeDef* TIMx, uint16_t Compare1);void TIM_SetCompare2(TIM_TypeDef* TIMx, uint16_t Compare2);void TIM_SetCompare3(TIM_TypeDef* TIMx, uint16_t Compare3);void TIM_SetCompare4(TIM_TypeDef* TIMx, uint16_t Compare4);  void TIM_SetIC1Prescaler(TIM_TypeDef* TIMx, uint16_t TIM_ICPSC);  void TIM_SetIC2Prescaler(TIM_TypeDef* TIMx, uint16_t TIM_ICPSC);  void TIM_SetIC3Prescaler(TIM_TypeDef* TIMx, uint16_t TIM_ICPSC);  void TIM_SetIC4Prescaler(TIM_TypeDef* TIMx, uint16_t TIM_ICPSC);  void TIM_SetClockDivision(TIM_TypeDef* TIMx, uint16_t TIM_CKD);  uint16_t TIM_GetCapture1(TIM_TypeDef* TIMx);  uint16_t TIM_GetCapture2(TIM_TypeDef* TIMx);  uint16_t TIM_GetCapture3(TIM_TypeDef* TIMx);  uint16_t TIM_GetCapture4(TIM_TypeDef* TIMx); //获取当前计数器的值，返回值就是当前计数器的值uint16_t TIM_GetCounter(TIM_TypeDef* TIMx); //获取当前预分频器的值，返回值就是当前预分频器的值uint16_t TIM_GetPrescaler(TIM_TypeDef* TIMx); //获取TIM标志位FlagStatus TIM_GetFlagStatus(TIM_TypeDef* TIMx, uint16_t TIM_FLAG); //清除TIM标志位void TIM_ClearFlag(TIM_TypeDef* TIMx, uint16_t TIM_FLAG); //获取定时器中断标志位ITStatus TIM_GetITStatus(TIM_TypeDef* TIMx, uint16_t TIM_IT); //清除定时器中断标志位void TIM_ClearITPendingBit(TIM_TypeDef* TIMx, uint16_t TIM_IT);

