#include &quot;Device/Include/stm32f10x.h&quot;   // Device header/*	开启时钟步骤	1.RCC开启时钟	2.选择时基单元的时钟源，对于定时中断，选择内部时钟源	3.配置时基单元，包括预分频器PSC，自动重装器ARR，计数器CNT等	4.配置输出中断控制，允许更新中断输出到NVIC	5.配置NVIC，在NVIC中打开定时器中断的通道，并分配优先级	6.运行控制，使能定时器，编写中断函数*/void Task01_Timer_Init()//初始化TIM2通用定时器&#123;	//开启时钟	RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2,ENABLE);		//选择时基单元的时钟	TIM_InternalClockConfig(TIM2);		//初始化时基单元    定时频率 = 72M / （PSC + 1） / （ARR + 1）	TIM_TimeBaseInitTypeDef My_TimerBaseInitstructure;	My_TimerBaseInitstructure.TIM_ClockDivision = TIM_CKD_DIV1; //预分频值 	My_TimerBaseInitstructure.TIM_CounterMode = TIM_CounterMode_Up; //计数模式	My_TimerBaseInitstructure.TIM_Period = 10000 - 1; //ARR自动重装器的值	My_TimerBaseInitstructure.TIM_Prescaler = 7200 - 1; //PCS预分频器的值	My_TimerBaseInitstructure.TIM_RepetitionCounter = 0; //重复计数器的值	TIM_TimeBaseInit(TIM2,&amp;My_TimerBaseInitstructure);			TIM_ClearFlag(TIM2,TIM_CounterMode_Up);//避免刚初始化完就进行一次中断			//使能定时器中断,TIM_IT_Update为更新中断	TIM_ITConfig(TIM2,TIM_IT_Update,ENABLE);		//配置中断控制器NVIC	NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);		//配置中断通道以及优先级相关,开启中断	NVIC_InitTypeDef My_NVICStructure;	My_NVICStructure.NVIC_IRQChannel = TIM2_IRQn;	My_NVICStructure.NVIC_IRQChannelCmd = ENABLE;	My_NVICStructure.NVIC_IRQChannelPreemptionPriority = 2;	My_NVICStructure.NVIC_IRQChannelSubPriority = 1;	NVIC_Init(&amp;My_NVICStructure);		//启动定时器	TIM_Cmd(TIM2,ENABLE);&#125; //编写TIM2的中断函数模板//void TIM2_IRQHandler(void)//&#123;//	if(TIM_GetITStatus(TIM2,TIM_IT_Update) == SET)//	&#123;//		//		TIM_ClearITPendingBit(TIM2,TIM_IT_Update);//	&#125;//&#125; void Task02_Timer_Init()//初始化TIM2通用定时器&#123;	//开启TIM2时钟	RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2,ENABLE);		//通过ETR引脚的外部时钟模式2配置	TIM_ETRClockMode2Config(TIM2,TIM_ExtTRGPSC_OFF,TIM_ExtTRGPolarity_NonInverted,0x00);		//初始化时基单元    定时频率 = 72M / （PSC + 1） / （ARR + 1）	TIM_TimeBaseInitTypeDef My_TimerBaseInitstructure;	My_TimerBaseInitstructure.TIM_ClockDivision = TIM_CKD_DIV1; //预分频值 	My_TimerBaseInitstructure.TIM_CounterMode = TIM_CounterMode_Up; //计数模式	My_TimerBaseInitstructure.TIM_Period = 10000 - 1; //ARR自动重装器的值	My_TimerBaseInitstructure.TIM_Prescaler = 7200 - 1; //PCS预分频器的值	My_TimerBaseInitstructure.TIM_RepetitionCounter = 0; //重复计数器的值	TIM_TimeBaseInit(TIM2,&amp;My_TimerBaseInitstructure);			TIM_ClearFlag(TIM2,TIM_CounterMode_Up);//避免刚初始化完就进行一次中断			//使能定时器中断,TIM_IT_Update为更新中断	TIM_ITConfig(TIM2,TIM_IT_Update,ENABLE);		//配置中断控制器NVIC	NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);		//配置中断通道以及优先级相关,开启中断	NVIC_InitTypeDef My_NVICStructure;	My_NVICStructure.NVIC_IRQChannel = TIM2_IRQn;	My_NVICStructure.NVIC_IRQChannelCmd = ENABLE;	My_NVICStructure.NVIC_IRQChannelPreemptionPriority = 2;	My_NVICStructure.NVIC_IRQChannelSubPriority = 1;	NVIC_Init(&amp;My_NVICStructure);		//启动定时器	TIM_Cmd(TIM2,ENABLE);		//配置GPIO口	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA,ENABLE);	GPIO_InitTypeDef My_GPIO_InitStructure;	My_GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;	My_GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;	My_GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;	GPIO_Init(GPIOA,&amp;My_GPIO_InitStructure);&#125; uint16_t Timer_GetCounter(void)&#123;	return TIM_GetCounter(TIM2);&#125;

以上代码是STM32微控制器的一个定时器初始化函数 Timer_Init。这个函数配置了TIM2定时器，设置了定时器的时钟源、分频系数和计数周期，并启用了定时器更新中断。下面是代码逐行解释：
void Timer_Init(void)&#123;    // 启用TIM2外设时钟    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);    // 配置TIM2使用内部时钟    TIM_InternalClockConfig(TIM2);    // 定义并初始化TIM_TimeBaseInitTypeDef结构体    TIM_TimeBaseInitTypeDef TIM_TimeBaseInitStructure;        // 设置定时器时钟分频因子    TIM_TimeBaseInitStructure.TIM_ClockDivision = TIM_CKD_DIV1;        // 设置计数模式为向上计数    TIM_TimeBaseInitStructure.TIM_CounterMode = TIM_CounterMode_Up;        // 设置自动重装载寄存器值，计数周期    TIM_TimeBaseInitStructure.TIM_Period = 10000 - 1;        // 设置预分频器值，分频系数    TIM_TimeBaseInitStructure.TIM_Prescaler = 7200 - 1;        // 设置重复计数器值    TIM_TimeBaseInitStructure.TIM_RepetitionCounter = 0;        // 初始化TIM2定时器基准时间单位    TIM_TimeBaseInit(TIM2, &amp;TIM_TimeBaseInitStructure);    // 使能TIM2更新中断    TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);&#125;


RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);

使能TIM2定时器的时钟。TIM2属于APB1总线上的外设，因此使用 RCC_APB1PeriphClockCmd 函数使能TIM2时钟。


TIM_InternalClockConfig(TIM2);

配置TIM2使用内部时钟源。


TIM_TimeBaseInitTypeDef TIM_TimeBaseInitStructure;

定义一个 TIM_TimeBaseInitTypeDef 类型的结构体变量，用于配置定时器的基本时间参数。


TIM_TimeBaseInitStructure.TIM_ClockDivision = TIM_CKD_DIV1;

设置时钟分频因子为1，即不分频。TIM_CKD_DIV1 表示直接使用输入时钟。


TIM_TimeBaseInitStructure.TIM_CounterMode = TIM_CounterMode_Up;

设置定时器的计数模式为向上计数。TIM_CounterMode_Up 表示定时器从0计数到 TIM_Period 的值。


TIM_TimeBaseInitStructure.TIM_Period = 10000 - 1;

设置自动重装载寄存器的值为9999。定时器的计数值从0到9999，即计数10000次后产生一次更新事件。


TIM_TimeBaseInitStructure.TIM_Prescaler = 7200 - 1;

设置预分频器的值为7199。预分频器将时钟频率分频为 7200。如果输入时钟为72 MHz，分频后的时钟为 10 kHz。


TIM_TimeBaseInitStructure.TIM_RepetitionCounter = 0;

设置重复计数器值为0，对于基本定时器，这个参数一般不使用。


TIM_TimeBaseInit(TIM2, &amp;TIM_TimeBaseInitStructure);

使用上述配置初始化TIM2定时器。


TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);

使能TIM2的更新中断。当定时器计数达到 TIM_Period 的值时会产生更新中断。



计时周期计算假设输入时钟为72 MHz，分频系数为7200，自动重装载值为10000：

计数频率 &#x3D; 输入时钟 &#x2F; 预分频值 &#x3D; 72 MHz &#x2F; 7200 &#x3D; 10 kHz
计数周期 &#x3D; (自动重装载值 + 1) &#x2F; 计数频率 &#x3D; 10000 &#x2F; 10 kHz &#x3D; 1 秒

因此，该配置使得TIM2每秒产生一次更新中断。
