6-7 TIM编码器接口







配置编码器测量步骤：
1.RCC开启时钟，开启GPIO和定时器时钟
2.配置相关GPIO，将CH1和CH2的IO口设置为输入模式
3.配置时基单元，预分频器一般不分频，自动重装一般给最大65535
4.配置输入捕获单元，只需配置通道、滤波器和极性即可，其他参数用不上
5.配置编码器接口模式，直接调用库函数
6.调用TIM_Cmd启动定时器

6-8 编码器接口测速
main.c
#include &quot;stm32f10x.h&quot;                  // Device header#include &quot;encoder.h&quot;#include &quot;OLED_I2C.h&quot;#include &quot;delay.h&quot;#include &lt;stdio.h&gt;//编码器接口测速//PA6接A相  PA7接B相  分别是TIM3的CH1  和  TIM3的CH2  uint16_t temp = 0; void DisplayIntegerValue(int value)&#123;    char str[16]; // 用于存储转换后的字符串    snprintf(str, sizeof(str), &quot;temp: %d&quot;, value); // 将整数转换为字符串    OLED_ShowStr(1, 1, (unsigned char *)str, 1); // 在OLED上显示字符串&#125; int main(void)&#123;    DelayInit();    I2C_Configuration();    OLED_Init();        Encoder_Init();    OLED_Fill(0xFF);    DelayS(2);     OLED_CLS();	while (1)	&#123;      temp = Encoder_Get();      DisplayIntegerValue(temp);        DelayS(1);	&#125;&#125;

