7-2 AD单通道&amp;AD多通道

STM32f103c8t6只有ADC1和ADC2，且无PC部分的端口
有四种转换模式









配置ADC的步骤：
1.开启RCC时钟，包括ADC和GPIO时钟，ADCCLK的分配器也需配置RCC_用ADCCLKConfig()
2.配置GPIO,将信号输入的端口配置成模拟输入
3.配置多路开关，将左边的通道接入到右边的规则组列表里
4.配置ADC转换器，结构体里面的参数有选择转换模式，是否扫描，通道个数设置，触发源设置，数据对齐方式等。
5.开启ADC，调用ADC_Cmd函数。如若需要，可加入校准步骤。

 main.c
#include &quot;stm32f10x.h&quot;                  // Device header#include &quot;OLED.h&quot;#include &quot;delay.h&quot;#include &quot;task01.h&quot;#include &quot;task02.h&quot;  //任务1  AD单通道//电位器：一个可调电阻，有三个端口，其中两个连接正负极，一个连接A0uint16_t task01_AD_value;float task01_Volatge; void Task01()&#123;    OLED_Init();    Task01_Init();    OLED_ShowString(1,1,&quot;ADValue:&quot;);    OLED_ShowString(2,1,&quot;Volatge:0.00V&quot;);    while(1)    &#123;        task01_AD_value = Task01_AD_GetValue();        task01_Volatge = (float)task01_AD_value / 4095 * 3.3;        OLED_ShowNum(1,9,task01_AD_value,4);        OLED_ShowNum(2,9,task01_Volatge,1);        OLED_ShowNum(2,11,(uint16_t)(task01_Volatge * 100) % 100,2);               Delay_ms(100);    &#125;&#125;  //任务2  AD多通道//PA0接电位器 PA1接光温传感器 PA2接热敏传感器 PA3接反射式红外传感器uint16_t AD0;uint16_t AD1;uint16_t AD2;uint16_t AD3;void Task02()&#123;    OLED_Init();    Task02_Init();    OLED_ShowString(1,1,&quot;AD0:0000&quot;);    OLED_ShowString(2,1,&quot;AD1:9999&quot;);    OLED_ShowString(3,1,&quot;AD2:9999&quot;);    OLED_ShowString(4,1,&quot;AD3:9999&quot;);    while(1)    &#123;        AD0 = Task02_AD_GetValue(ADC_Channel_0);        AD1 = Task02_AD_GetValue(ADC_Channel_1);        AD2 = Task02_AD_GetValue(ADC_Channel_2);        AD3 = Task02_AD_GetValue(ADC_Channel_3);                OLED_ShowNum(1,5,AD0,4);        OLED_ShowNum(2,5,AD1,4);        OLED_ShowNum(3,5,AD2,4);        OLED_ShowNum(4,5,AD3,4);                Delay_ms(100);    &#125;&#125; int main(void)&#123;//    Task02();	while (1)	&#123;			&#125;&#125;

