#include &quot;task01.h&quot; //配置单次转换，非扫描模式ADCvoid Task01_Init()&#123;    //开启RCC时钟    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA,ENABLE);    RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1,ENABLE);        //ADCCLK分配器配置    RCC_ADCCLKConfig(RCC_PCLK2_Div6);        //配置GPIO为模拟输入模式    GPIO_InitTypeDef My_GPIO_InitStructure;    My_GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;    My_GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AIN;//模拟输入模式，AIN模式是ADC的专属模式    My_GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    GPIO_Init(GPIOA,&amp;My_GPIO_InitStructure);        //选择规则组的输入通道    ADC_RegularChannelConfig(ADC1,ADC_Channel_0,1,ADC_SampleTime_55Cycles5);        //初始化ADC    ADC_InitTypeDef My_ADC_InitStructure;    My_ADC_InitStructure.ADC_ContinuousConvMode = DISABLE;//单次转换模式    My_ADC_InitStructure.ADC_DataAlign = ADC_DataAlign_Right;//数据右对齐    My_ADC_InitStructure.ADC_ExternalTrigConv = ADC_ExternalTrigConv_None;//外部触发源选择，这里是无触发源，用软件触发就选这个参数    My_ADC_InitStructure.ADC_Mode = ADC_Mode_Independent;//独立模式    My_ADC_InitStructure.ADC_NbrOfChannel = 1;//选择通道一    My_ADC_InitStructure.ADC_ScanConvMode = DISABLE;//单通道模式    ADC_Init(ADC1,&amp;My_ADC_InitStructure);        //开启ADC电源    ADC_Cmd(ADC1,ENABLE);        //校准    //1.复位校准    ADC_ResetCalibration(ADC1);    //2.等待复位校准完成    while(ADC_GetResetCalibrationStatus(ADC1) == SET);    //3.开始校准    ADC_StartCalibration(ADC1);    //4.获取校准标志位,等待校准完成    while(ADC_GetCalibrationStatus(ADC1) == SET);&#125; //获取ADC的数据uint16_t Task01_AD_GetValue(void)&#123;    ADC_SoftwareStartConvCmd(ADC1,ENABLE);//软件触发转换    while(ADC_GetFlagStatus(ADC1,ADC_FLAG_EOC) == RESET);//等待转换完成    return ADC_GetConversionValue(ADC1);&#125;

#include &quot;task02.h&quot; void Task02_Init()&#123;    //开启RCC时钟    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA,ENABLE);    RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1,ENABLE);        //配置ADCCLK预分频器    RCC_ADCCLKConfig(RCC_PCLK2_Div6);        //配置GPIO为模拟输入    GPIO_InitTypeDef My_GPIO_InitStructure;    My_GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0 | GPIO_Pin_1 | GPIO_Pin_2 | GPIO_Pin_3;    My_GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AIN;    My_GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    GPIO_Init(GPIOA,&amp;My_GPIO_InitStructure);        //ADC_RegularChannelConfig(ADC1,ADC_Channel_0,1,ADC_SampleTime_55Cycles5);        //初始化ADC    ADC_InitTypeDef My_ADC_InitStructure;    My_ADC_InitStructure.ADC_ContinuousConvMode = DISABLE;//单次转换    My_ADC_InitStructure.ADC_DataAlign = ADC_DataAlign_Right;//数据右对齐    My_ADC_InitStructure.ADC_ExternalTrigConv = ADC_ExternalTrigConv_None;//无触发源，由软件触发    My_ADC_InitStructure.ADC_Mode = ADC_Mode_Independent;//独立模式    My_ADC_InitStructure.ADC_NbrOfChannel = 1;//选择通道1    My_ADC_InitStructure.ADC_ScanConvMode = DISABLE;//单通道模式    ADC_Init(ADC1,&amp;My_ADC_InitStructure);        //开启ADC电源    ADC_Cmd(ADC1,ENABLE);        //校准数据    //复位校准    ADC_ResetCalibration(ADC1);    //等待复位校准完成    while(ADC_GetResetCalibrationStatus(ADC1) == SET);    //开始校准    ADC_StartCalibration(ADC1);    //等待校准完成    while(ADC_GetCalibrationStatus(ADC1) == SET);&#125; uint16_t Task02_AD_GetValue(uint8_t ADC_Channel)&#123;    //选择规则组的输入通道    ADC_RegularChannelConfig(ADC1,ADC_Channel,1,ADC_SampleTime_55Cycles5);    ADC_SoftwareStartConvCmd(ADC1,ENABLE);//软件触发转换    while(ADC_GetFlagStatus(ADC1,ADC_FLAG_EOC) == RESET);//等待转换完成    return ADC_GetConversionValue(ADC1); //获取数据&#125;

