#include &quot;task01.h&quot; uint16_t My_Size; void Task01_Init(uint32_t ADDrA,uint32_t ADDrB,uint16_t Size)//数据从ADDrA-&gt;ADDrB,A是外设，B是存储器&#123;    My_Size = Size;    //初始化DMA    RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1,ENABLE);//开启RCC时钟        DMA_Cmd(DMA1_Channel1,DISABLE);//先失能DMA        DMA_InitTypeDef My_DMA_InitStructure;    My_DMA_InitStructure.DMA_BufferSize = Size;//缓存区大小，即传输计数器 0~65535    My_DMA_InitStructure.DMA_DIR = DMA_DIR_PeripheralSRC;//传输方向    //DST是指外设站点作为目的地，SRC是指外设站点作为源头    My_DMA_InitStructure.DMA_M2M = DMA_M2M_Enable;//是否使用存储器到存储器，即选择软件触发还是硬件触发    My_DMA_InitStructure.DMA_MemoryBaseAddr = ADDrB;//存储器站点的起始地址    My_DMA_InitStructure.DMA_MemoryDataSize = DMA_MemoryDataSize_Byte;//存储器站点的数据宽度    My_DMA_InitStructure.DMA_MemoryInc = DMA_MemoryInc_Enable;//存储器站点地址是否递增    My_DMA_InitStructure.DMA_Mode = DMA_Mode_Normal;//传输模式，选择是否使用自动重装    //DMA的软件触发和自动重装不能同时启用，否则无法停下    My_DMA_InitStructure.DMA_PeripheralBaseAddr = ADDrA;//外设站点的起始地址    My_DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Byte;//外设站点的数据宽度    My_DMA_InitStructure.DMA_PeripheralInc = DMA_PeripheralInc_Enable;//外设外设站点地址是否递增。    My_DMA_InitStructure.DMA_Priority = DMA_Priority_Medium;//优先级配置。    DMA_Init(DMA1_Channel1,&amp;My_DMA_InitStructure);        DMA_Cmd(DMA1_Channel1,ENABLE);&#125; void Task01_DMA_Transfer(void)&#123;        DMA_Cmd(DMA1_Channel1,DISABLE);    DMA_SetCurrDataCounter(DMA1_Channel1,My_Size);    DMA_Cmd(DMA1_Channel1,ENABLE);        //等待转运完成    while(DMA_GetFlagStatus(DMA1_FLAG_GL1) == RESET);    DMA_ClearFlag(DMA1_FLAG_GL1);&#125;

