#include &quot;task02.h&quot; uint16_t AD_Value[4]; void Task02_Init()&#123;        RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1,ENABLE);//开启DMA时钟    RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1,ENABLE);//开启ADC1时钟    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA,ENABLE);//开启GPIOA时钟        //配置ADC    GPIO_InitTypeDef My_GPIO_InitStructure;    My_GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0 | GPIO_Pin_1 | GPIO_Pin_2 | GPIO_Pin_3 ;    My_GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AIN;    My_GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    GPIO_Init(GPIOA,&amp;My_GPIO_InitStructure);    //配置GPIO        RCC_ADCCLKConfig(RCC_PCLK2_Div6);    //ADC预分频        ADC_RegularChannelConfig(ADC1,ADC_Channel_0,1,ADC_SampleTime_55Cycles5);    ADC_RegularChannelConfig(ADC1,ADC_Channel_1,2,ADC_SampleTime_55Cycles5);    ADC_RegularChannelConfig(ADC1,ADC_Channel_2,3,ADC_SampleTime_55Cycles5);    ADC_RegularChannelConfig(ADC1,ADC_Channel_3,4,ADC_SampleTime_55Cycles5);        ADC_InitTypeDef My_ADC_InitStructure;    My_ADC_InitStructure.ADC_ContinuousConvMode = DISABLE;//是否连续转换模式    My_ADC_InitStructure.ADC_DataAlign = ADC_DataAlign_Right;//数据右对齐    My_ADC_InitStructure.ADC_ExternalTrigConv = ADC_ExternalTrigConv_None;//不接触发源    My_ADC_InitStructure.ADC_Mode = ADC_Mode_Independent;//ADC为独立模式    My_ADC_InitStructure.ADC_NbrOfChannel = 4;    My_ADC_InitStructure.ADC_ScanConvMode = ENABLE;//配置多通道模式    ADC_Init(ADC1,&amp;My_ADC_InitStructure);//初始化ADC             DMA_Cmd(DMA1_Channel1,DISABLE);//先失能DMA        DMA_InitTypeDef My_DMA_InitStructure;    My_DMA_InitStructure.DMA_BufferSize = 4;//缓存区大小，即传输计数器 0~65535    My_DMA_InitStructure.DMA_DIR = DMA_DIR_PeripheralSRC;//传输方向    //DST是指外设站点作为目的地，SRC是指外设站点作为源头    My_DMA_InitStructure.DMA_M2M = DMA_M2M_Disable;//是否使用存储器到存储器，即选择软件触发还是硬件触发    My_DMA_InitStructure.DMA_MemoryBaseAddr = (uint32_t)AD_Value;//存储器站点的起始地址    My_DMA_InitStructure.DMA_MemoryDataSize = DMA_PeripheralDataSize_HalfWord;//存储器站点的数据宽度    My_DMA_InitStructure.DMA_MemoryInc = DMA_MemoryInc_Enable;//存储器站点地址是否递增    My_DMA_InitStructure.DMA_Mode = DMA_Mode_Normal;//传输模式，选择是否使用自动重装    //DMA的软件触发和自动重装不能同时启用，否则无法停下    My_DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&amp;ADC1-&gt;DR;//外设站点的起始地址    My_DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_HalfWord;//外设站点的数据宽度    My_DMA_InitStructure.DMA_PeripheralInc = DMA_PeripheralInc_Disable;//外设外设站点地址是否递增。    My_DMA_InitStructure.DMA_Priority = DMA_Priority_Medium;//优先级配置。    DMA_Init(DMA1_Channel1,&amp;My_DMA_InitStructure);        DMA_Cmd(DMA1_Channel1,ENABLE);//使能DMA        ADC_DMACmd(ADC1,ENABLE);//将ADC触发DMA开启    ADC_Cmd(ADC1,ENABLE);//开启ADC        //因使用多通道的ADC，要检验数据    //复位校准    ADC_ResetCalibration(ADC1);    //等待校准复位完毕    while(ADC_GetResetCalibrationStatus(ADC1) == SET);    //开启校准    ADC_StartCalibration(ADC1);    //等待校准完毕    while(ADC_GetCalibrationStatus(ADC1) == SET);&#125;  void Task02_AD_GetValue(void)&#123;     DMA_Cmd(DMA1_Channel1,DISABLE);    DMA_SetCurrDataCounter(DMA1_Channel1,4);    DMA_Cmd(DMA1_Channel1,ENABLE);        ADC_SoftwareStartConvCmd(ADC1,ENABLE);//软件触发转换        //等待转运完成    while(DMA_GetFlagStatus(DMA1_FLAG_GL1) == RESET);    DMA_ClearFlag(DMA1_FLAG_GL1);&#125;

