Tx, uint16_t USART_IrDAMode); //串口的IrDA接口启停void USART_IrDACmd(USART_TypeDef* USARTx, FunctionalState NewState); //获取串口标志位FlagStatus USART_GetFlagStatus(USART_TypeDef* USARTx, uint16_t USART_FLAG); //清除串口标志位void USART_ClearFlag(USART_TypeDef* USARTx, uint16_t USART_FLAG); //获取串口中断标志位ITStatus USART_GetITStatus(USART_TypeDef* USARTx, uint16_t USART_IT); //清除串口中断标志位void USART_ClearITPendingBit(USART_TypeDef* USARTx, uint16_t USART_IT);

