#include &quot;task01.h&quot;  void Task01_Init(void)&#123;    //开启时钟    RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1, ENABLE);	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);            //GPIO初始化 配置成复用输入输出 PA9是TX   PA10RX    GPIO_InitTypeDef My_GPIO_InitStructure;    My_GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9;    My_GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;//复用推挽输出    My_GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    GPIO_Init(GPIOA,&amp;My_GPIO_InitStructure);//    My_GPIO_InitStructure.GPIO_Pin = GPIO_Pin_10;//    My_GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;//浮空输入//    GPIO_Init(GPIOA,&amp;My_GPIO_InitStructure);        //串口初始化    USART_InitTypeDef My_USART_InitStructure;    My_USART_InitStructure.USART_BaudRate = 9600;//波特率    My_USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;//不使用硬件流控模式    My_USART_InitStructure.USART_Mode = USART_Mode_Tx;//配置为发送模式    My_USART_InitStructure.USART_Parity = USART_Parity_No;//无校验位    My_USART_InitStructure.USART_StopBits = USART_StopBits_1;//1个停止位    My_USART_InitStructure.USART_WordLength = USART_WordLength_8b;//数据位数    USART_Init(USART1,&amp;My_USART_InitStructure);        //使能串口    USART_Cmd(USART1,ENABLE); &#125; void Task01_USART1_SendByte(uint8_t Data)&#123;    USART_SendData(USART1,Data);//发送后需要等待数据全部发送完成    while(USART_GetFlagStatus(USART1,USART_FLAG_TXE) == RESET);//等待发送完成    //标志位无需清零，每次调用SendData函数的时候会清零&#125; //发送数组void Task01_Serial_SendArray(uint16_t *Array,uint32_t Length)&#123;    uint16_t i;    for(i = 0;i &lt; Length; i++)    &#123;        Task01_USART1_SendByte(Array[i]);    &#125;&#125; //发送字符串void Task01_Serial_SendString(char *String)//   /r/n可以回车换行&#123;    uint16_t i;    for(i = 0;String[i] != &#x27;\0&#x27;;i++)    &#123;        Task01_USART1_SendByte(String[i]);    &#125;&#125; //辅助发送数字的函数，输出的是x的y次方uint32_t Task01_Serial_Pow(uint32_t X,uint32_t Y)&#123;    uint32_t Resuit = 1;    while(Y--)    &#123;        Resuit *= X;    &#125;    return Resuit;&#125; //发送数字void Task01_Serial_SendNumber(uint32_t Number,uint8_t Length)&#123;    uint16_t i;    for(i = 0;i &lt; Length;i++)    &#123;        Task01_USART1_SendByte(Number / Task01_Serial_Pow(10,Length - i - 1) % 10 + &#x27;0&#x27;);    &#125;&#125; //printf重定向int fputc(int ch,FILE *f)&#123;    Task01_USART1_SendByte(ch);    return ch;    &#125; void Task01_Serial_Printf(char *format,...)&#123;    char String[100];    va_list arg;    va_start(arg,format);    vsprintf(String,format,arg);    va_end(arg);    Task01_Serial_SendString(String);&#125;

