#include &quot;task02.h&quot;  void Task02_Init(void)&#123;    //初始化串口，让其发送+接收        //开始RCC    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA,ENABLE);    RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1,ENABLE);    RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO,ENABLE);            //初始化GPIO  PA9是单片机的TX  PA10是单片机的RX    GPIO_InitTypeDef My_GPIO_IniterStructure;    My_GPIO_IniterStructure.GPIO_Pin = GPIO_Pin_9;    My_GPIO_IniterStructure.GPIO_Mode = GPIO_Mode_AF_PP;//输出口配为复用输出    My_GPIO_IniterStructure.GPIO_Speed = GPIO_Speed_50MHz;    GPIO_Init(GPIOA,&amp;My_GPIO_IniterStructure);    My_GPIO_IniterStructure.GPIO_Pin = GPIO_Pin_10;    My_GPIO_IniterStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;//输入口配为复用浮空输入    GPIO_Init(GPIOA,&amp;My_GPIO_IniterStructure);        //USART初始化    USART_InitTypeDef My_USART_InitStructure;    My_USART_InitStructure.USART_BaudRate = 9600;//波特率设置    My_USART_InitStructure.USART_HardwareFlowControl = DISABLE;//禁用硬件流控制    My_USART_InitStructure.USART_Mode = USART_Mode_Rx | USART_Mode_Tx;//配置为发送+接收的模式    My_USART_InitStructure.USART_Parity = USART_Parity_No;//不使用校验位    My_USART_InitStructure.USART_StopBits = USART_StopBits_1;//1个停止位    My_USART_InitStructure.USART_WordLength = USART_WordLength_8b;//有效数据长度为八位    USART_Init(USART1,&amp;My_USART_InitStructure);        //接收模式可配置中断    USART_ITConfig(USART1,USART_IT_RXNE,ENABLE);//开启串口的接收中断、    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);//NVIC分组    NVIC_InitTypeDef My_NVIC_InitStructure;    My_NVIC_InitStructure.NVIC_IRQChannel = USART1_IRQn;    My_NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;    My_NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;    My_NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1;    NVIC_Init(&amp;My_NVIC_InitStructure);//初始化NVIC（中断管理器）         //使能串口    USART_Cmd(USART1,ENABLE);&#125; //串口发送函数void Task02_USART1_SendByte(uint8_t Data)&#123;    USART_SendData(USART1,Data);    while(USART_GetFlagStatus(USART1,USART_FLAG_TXE) == RESET);//等待发送完成    //标志位不用清零，每次使用USART_SendData时会自动清零&#125; //串口发送数组void Task02_Serial_SendArray(uint16_t *Array,uint32_t Length)&#123;    uint16_t i;    for(i = 0;i &lt; Length;i++)    &#123;        Task02_USART1_SendByte(Array[i]);    &#125;&#125; //串口发送字符串void Task02_Serial_SendString(char *String)&#123;    uint16_t i;    for(i = 0;String[i] != &#x27;\0&#x27;;i++)    &#123;        Task02_USART1_SendByte(String[i]);    &#125;&#125; //辅助发送数字的函数uint32_t Task02_Serial_Pow(uint32_t X,uint32_t Y)&#123;    uint32_t Resuit = 1;    while(Y--)    &#123;        Resuit *= X;    &#125;    return Resuit;&#125; //串口发送数字void Task02_Serial_SendNumber(int32_t Number,uint8_t Length)&#123;    uint16_t i;    for(i = 0;i &lt; Length;i++)    &#123;        Task02_USART1_SendByte(Number / Task02_Serial_Pow(10,Length - i - 1) % 10 + &#x27;0&#x27;);    &#125;&#125; printf重定向//int fputc(int ch,FILE *f)//&#123;//    Task02_USART1_SendByte(ch);//    return ch;//    //&#125; uint8_t Task02_Serial_RxData;uint8_t Task02_Serial_RxFlag; uint8_t Task02_GetSerial_RxFlag(void)&#123;    if(Task02_Serial_RxFlag == 1)    &#123;        Task02_Serial_RxFlag = 0;        return 1;    &#125;    return 0;&#125; uint8_t Task02_GetSerial_RxData(void)&#123;    return Task02_Serial_RxData;&#125; void USART1_IRQHandler(void)&#123;    if(USART_GetITStatus(USART1,USART_IT_RXNE) == SET)    &#123;        Task02_Serial_RxData = USART_ReceiveData(USART1);        Task02_Serial_RxFlag = 1;        USART_ClearITPendingBit(USART1,USART_IT_RXNE);//手动清除中断标志位    &#125;&#125;
